() => {
  const sel = document.querySelectorAll('select');
  const result = [];
  sel.forEach((s, i) => {
    result.push({index: i, id: s.id, value: s.value, options: Array.from(s.options).map(o => ({value: o.value, text: o.text, selected: o.selected}))});
  });
  return result;
}

