() => {
  // Find all elements that might contain price information
  const priceElements = document.querySelectorAll('[class*="price"], [class*="Price"], [class*="cost"], [data-pricing]');
  const result = [];
  priceElements.forEach(el => {
    result.push({tag: el.tagName, class: el.className, text: el.textContent.substring(0, 200)});
  });

  // Also look at the comparison data
  const compareData = document.querySelectorAll('.compare-item-info, [class*="compare"]');

  return JSON.stringify({prices: result.slice(0, 20), compare: compareData.length});
}
